-- GENERATED by pipeline/make_dbt_staging.py from sources.json
-- and the extract's club folders; edit them or it, never this file.
{{ config(materialized='table') }}
-- Every trail lines row of the clubs' registered ArcGIS layers that
-- pipeline/make_dbt_staging.py stages, one row each, unfiltered: a `union
-- all by name` of every stg_<folder>__trail_lines it writes. The branch
-- list is the registry's, written by the generator from sources.json and
-- the extract's club folders, so a layer registered later joins by running
-- it again. Nothing reads this yet: every layer here is held back by its
-- sources.json row, and a mart that reads it must keep
-- int_sources__publication's verdict.
select
    source_key,
    club,
    trail_segment_key,
    name,
    geom,
    properties,
    _loaded_at
from {{ ref('stg_ata__trail_lines') }}
union all by name
